"""Validate competitors/raw/us_premium_others.jsonl against README schema rules.
Usage: python3 -I validate_upo.py <repo_root> <jsonl> <fetched_list>
"""
import json
import sys
from collections import Counter
from pathlib import Path

root = Path(sys.argv[1])
jsonl = Path(sys.argv[2])
fetched = set(l.strip() for l in Path(sys.argv[3]).read_text().splitlines() if l.strip())
themes = json.loads((root / "competitors/themes.json").read_text())
theme_ids = {t["id"] for t in themes["themes"]}
vfc = themes["vfc_level2_to_theme"]
FT = set(themes["feedback_types"])
CMP = set(themes["comparison_values"]) | {None}
FEATS = {
    "F01_display_layout": "hmi_infotainment", "F02_hud": "hmi_infotainment",
    "F03_physical_climate_controls": "climate", "F04_voice_assistant": "hmi_infotainment",
    "F05_wireless_carplay_aa": "connectivity_app_digital", "F06_ota_updates": "connectivity_app_digital",
    "F07_digital_key": "access_locking", "F08_hands_free_highway": "adas_parking",
    "F09_automated_parking": "adas_parking", "F10_ventilated_front_seats": "seats_comfort",
    "F11_massage_seats": "seats_comfort", "F12_rear_comfort": "seats_comfort",
    "F13_air_suspension": "ride_handling", "F14_rear_wheel_steering": "ride_handling",
    "F15_bev_range": "range_charging_efficiency", "F16_dc_charging": "range_charging_efficiency",
    "F17_rear_space": "space_practicality", "F18_trunk_volume": "space_practicality",
    "F19_premium_audio": "audio_acoustics", "F20_panoramic_roof": "interior_design_quality",
}
FB_FIELDS = ["record_id", "review_ref", "kind", "market", "country", "brand", "model", "generation",
             "model_year", "powertrain", "source_type", "source_name", "url", "published",
             "feedback_type", "theme", "vfc_level2", "comparison", "statement", "quote",
             "language", "rating", "evidence_tier"]
EQ_FIELDS = ["record_id", "kind", "market", "brand", "model", "generation", "trim_scope", "feature",
             "theme", "availability", "value", "source_type", "url", "as_of", "evidence_tier", "notes"]
C_FIELDS = ["record_id", "kind", "market", "brand", "model", "generation", "powertrains", "launched",
            "rationale", "next_generation", "next_generation_evidence_tier", "url"]
errs = []
ids = Counter()
stats = Counter()
refs = {}
eqkeys = Counter()
for n, line in enumerate(jsonl.read_text(encoding="utf-8").splitlines(), 1):
    if not line.strip():
        errs.append(f"L{n}: blank line")
        continue
    try:
        r = json.loads(line)
    except Exception as e:
        errs.append(f"L{n}: bad json {e}")
        continue
    ids[r.get("record_id")] += 1
    k = r.get("kind")
    if r.get("url") not in fetched:
        errs.append(f"L{n} {r.get('record_id')}: url not in fetched list: {r.get('url')}")
    if k == "feedback":
        miss = [f for f in FB_FIELDS if f not in r]
        extra = [f for f in r if f not in FB_FIELDS]
        if miss or extra:
            errs.append(f"L{n}: fields missing {miss} extra {extra}")
            continue
        if r["feedback_type"] not in FT: errs.append(f"L{n}: bad feedback_type {r['feedback_type']}")
        if r["theme"] not in theme_ids: errs.append(f"L{n}: bad theme {r['theme']}")
        if r["vfc_level2"] is not None:
            if r["vfc_level2"] not in vfc: errs.append(f"L{n}: bad vfc {r['vfc_level2']}")
            elif vfc[r["vfc_level2"]] != r["theme"]: errs.append(f"L{n}: vfc {r['vfc_level2']} -> {vfc[r['vfc_level2']]} != {r['theme']}")
        if r["comparison"] not in CMP: errs.append(f"L{n}: bad comparison")
        if r["powertrain"] not in {"ICE", "PHEV", "BEV", "unknown"}: errs.append(f"L{n}: bad powertrain")
        if r["source_type"] not in {"owner_review", "owner_forum", "owner_survey", "press_review"}: errs.append(f"L{n}: bad source_type")
        if r["evidence_tier"] not in {"A", "B"}: errs.append(f"L{n}: bad tier")
        if (r["source_type"] == "press_review") != (r["evidence_tier"] == "B"): errs.append(f"L{n}: tier/source mismatch")
        if r["quote"] and len(r["quote"].split()) >= 15: errs.append(f"L{n}: quote too long")
        if r["market"] != "US": errs.append(f"L{n}: market")
        if not r["record_id"].startswith("us_premium_others-F"): errs.append(f"L{n}: id prefix")
        if not r["review_ref"].startswith("us_premium_others-R"): errs.append(f"L{n}: ref prefix")
        key = r["review_ref"]
        meta = (r["model"], r["generation"], r["url"], r["source_type"], r["published"], r["model_year"])
        if key in refs and refs[key] != meta: errs.append(f"L{n}: review_ref {key} inconsistent meta")
        refs[key] = meta
        stats[(r["brand"] + " " + r["model"], r["generation"], "feedback", r["source_type"])] += 1
    elif k == "equipment":
        miss = [f for f in EQ_FIELDS if f not in r]
        extra = [f for f in r if f not in EQ_FIELDS]
        if miss or extra:
            errs.append(f"L{n}: fields missing {miss} extra {extra}")
            continue
        if r["feature"] not in FEATS: errs.append(f"L{n}: bad feature {r['feature']}")
        elif FEATS[r["feature"]] != r["theme"]: errs.append(f"L{n}: feature theme mismatch")
        if r["availability"] not in {"standard", "optional", "not_available", "unknown"}: errs.append(f"L{n}: availability")
        if r["source_type"] not in {"manufacturer", "press_review"}: errs.append(f"L{n}: eq source_type")
        elif {"manufacturer": "C", "press_review": "B"}[r["source_type"]] != r["evidence_tier"]: errs.append(f"L{n}: eq tier")
        eqkeys[(r["generation"], r["feature"])] += 1
        stats[(r["brand"] + " " + r["model"], r["generation"], "equipment", "")] += 1
    elif k == "competitor":
        miss = [f for f in C_FIELDS if f not in r]
        extra = [f for f in r if f not in C_FIELDS]
        if miss or extra: errs.append(f"L{n}: fields missing {miss} extra {extra}")
        stats[(r["brand"] + " " + r["model"], r["generation"], "competitor", "")] += 1
    else:
        errs.append(f"L{n}: bad kind {k}")
for i, c in ids.items():
    if c > 1: errs.append(f"duplicate id {i}")
print("\n".join(errs) if errs else "NO ERRORS")
for k_, v in sorted(stats.items()): print(k_, v)
uref = Counter()
for key, meta in refs.items(): uref[(meta[0], meta[1], meta[3])] += 1
print("unique review_refs:")
for k_, v in sorted(uref.items()): print(" ", k_, v)
dup = [k_ for k_, v in eqkeys.items() if v > 1]
print("equipment feature duplicates per generation:", dup)

